const UNRESERVED_RE = /^[A-Za-z0-9\-._~]$/;
const RESERVED_CHARS = ":/?#[]@!$&'()*+,;=";
const HEX_RE = /^[0-9A-Fa-f]$/;

function isUnreserved(ch) {
  return UNRESERVED_RE.test(ch);
}

function isReserved(ch) {
  return RESERVED_CHARS.includes(ch);
}

function encodeCodepoint(ch) {
  const bytes = Buffer.from(ch, 'utf8');
  let out = '';
  for (const b of bytes) out += `%${b.toString(16).toUpperCase().padStart(2, '0')}`;
  return out;
}

/** Percent-encode text keeping unreserved chars, reserved chars and existing percent-triplets. */
function encodeLiteral(str) {
  const arr = Array.from(str);
  let out = '';
  for (let i = 0; i < arr.length; i += 1) {
    const ch = arr[i];
    if (isUnreserved(ch) || isReserved(ch)) {
      out += ch;
      continue;
    }
    if (ch === '%' && arr[i + 1] !== undefined && arr[i + 2] !== undefined && HEX_RE.test(arr[i + 1]) && HEX_RE.test(arr[i + 2])) {
      out += `%${arr[i + 1]}${arr[i + 2]}`;
      i += 2;
      continue;
    }
    out += encodeCodepoint(ch);
  }
  return out;
}

/** Percent-encode text keeping only unreserved characters. */
function encodeStrict(str) {
  const arr = Array.from(str);
  let out = '';
  for (const ch of arr) {
    out += isUnreserved(ch) ? ch : encodeCodepoint(ch);
  }
  return out;
}

function encodeForOperator(str, operator) {
  return operator === '+' || operator === '#' ? encodeLiteral(str) : encodeStrict(str);
}

function truncate(text, maxLength) {
  const arr = Array.from(text);
  if (arr.length <= maxLength) return text;
  return arr.slice(0, maxLength).join('');
}

function scalarToText(value, name) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (typeof value === 'boolean') return String(value);
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}

const OPERATOR_TABLE = {
  '': { prefix: '', separator: ',', named: false, emptyText: '' },
  '+': { prefix: '', separator: ',', named: false, emptyText: '' },
  '#': { prefix: '#', separator: ',', named: false, emptyText: '' },
  '.': { prefix: '.', separator: '.', named: false, emptyText: '' },
  '/': { prefix: '/', separator: '/', named: false, emptyText: '' },
  ';': { prefix: ';', separator: ';', named: true, emptyText: '' },
  '?': { prefix: '?', separator: '&', named: true, emptyText: '=' },
  '&': { prefix: '&', separator: '&', named: true, emptyText: '=' },
};

